def apply_overrides(cats, overrides):
    """Return CATS with service lines (and category intros, keyed by category id) replaced from overrides."""
    out = []
    for cid, title, intro, items in cats:
        intro = overrides.get(cid, intro)
        out.append((cid, title, intro, [(n, s, overrides.get(n, l)) for n, s, l in items]))
    return out
